package com.yonlab.vision;
import android.content.Context;import android.graphics.*;import org.tensorflow.lite.*;import java.nio.*;import java.io.*;import java.util.*;
final class OneEfficientNet implements AutoCloseable {
 private final Interpreter engine;private final boolean quantized;final String sha256;private boolean closed;
 OneEfficientNet(Context c,String id)throws Exception{quantized=id.endsWith("i8");OneLiteAsset asset=new OneLiteAsset(c,id+".tflite");sha256=asset.sha256;int threads=OneExecutionSettings.threads(c);Interpreter model=new Interpreter(asset.bytes,new Interpreter.Options().setNumThreads(threads));try{model.allocateTensors();if(!Arrays.equals(model.getInputTensor(0).shape(),new int[]{1,224,224,3})||!Arrays.equals(model.getOutputTensor(0).shape(),new int[]{1,1000})||model.getInputTensor(0).dataType()!=(quantized?DataType.UINT8:DataType.FLOAT32))throw new IOException("분류 모델 계약을 확인하세요");engine=model;}catch(Exception|Error e){model.close();throw e;}}
 synchronized float[] classify(Bitmap image)throws Exception{
  if(closed||Thread.currentThread().isInterrupted())throw new InterruptedIOException("canceled");int edge=Math.min(image.getWidth(),image.getHeight()),left=(image.getWidth()-edge)/2,top=(image.getHeight()-edge)/2;Bitmap scaled=Bitmap.createBitmap(224,224,Bitmap.Config.ARGB_8888);new Canvas(scaled).drawBitmap(image,new Rect(left,top,left+edge,top+edge),new Rect(0,0,224,224),new Paint(Paint.FILTER_BITMAP_FLAG));int[] pixels=new int[224*224];scaled.getPixels(pixels,0,224,0,0,224,224);scaled.recycle();ByteBuffer input=ByteBuffer.allocateDirect(pixels.length*3*(quantized?1:4)).order(ByteOrder.nativeOrder());Tensor.QuantizationParams q=engine.getInputTensor(0).quantizationParams();for(int p:pixels)for(int ch:new int[]{16,8,0}){float value=OneTensorMath.efficientNet((p>>>ch)&255);if(quantized)input.put((byte)OneTensorMath.quantize(value,q.getScale(),q.getZeroPoint()));else input.putFloat(value);}input.rewind();float[] scores=new float[1000];if(quantized){byte[][] out=new byte[1][1000];engine.run(input,out);Tensor.QuantizationParams oq=engine.getOutputTensor(0).quantizationParams();for(int i=0;i<1000;i++)scores[i]=((out[0][i]&255)-oq.getZeroPoint())*oq.getScale();}else{float[][] out=new float[1][1000];engine.run(input,out);scores=out[0];}for(float v:scores)if(!Float.isFinite(v)||v<0||v>1)throw new IOException("분류 출력을 확인하세요");return scores;
 }
 public synchronized void close(){if(!closed){closed=true;engine.close();}}
}
